import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"Plugin build tool","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/build/docs/index.md"},"headers":[],"relativePath":"tools/build/docs/index.md","filePath":"tools/build/docs/index.md","lastUpdated":1791801291000}'),n={name:"tools/build/docs/index.md"};function d(s,e,u,r,l,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="plugin-build-tool" tabindex="-1">Plugin build tool <a class="header-anchor" href="#plugin-build-tool" aria-label="Permalink to &quot;Plugin build tool&quot;">​</a></h1><p><code>@pumpkin-plugins/build</code> turns a plugin&#39;s TypeScript entry point into a Pumpkin WebAssembly component. It bundles the plugin, adds the WASI imports declared by the package, componentizes the module with the repository&#39;s pinned toolchain, and can generate guest declarations for typechecking.</p><h2 id="build-a-plugin" tabindex="-1">Build a plugin <a class="header-anchor" href="#build-a-plugin" aria-label="Permalink to &quot;Build a plugin&quot;">​</a></h2><p>Run <code>pnpm build</code> from a plugin package. The build configuration is the <code>pumpkinPlugin</code> object in that package&#39;s <code>package.json</code>; it identifies the entry point, output file, and requested WASI capabilities. The result is the configured <code>.wasm</code> file under the package&#39;s build directory. The optional <code>engine</code> setting defaults to <code>static-hermes</code>; set it to <code>quickjs</code> to build a QuickJS plugin. Both engines are supported, and current plugin packages use the Static Hermes default. Static Hermes is the WASI 2 backend described in the <a href="./../../static-hermes-runtime/README">runtime guide</a>. It uses the lean runtime archive by default. Set <code>staticHermesRuntime</code> to <code>&quot;full&quot;</code> to retain runtime source compilation, or set <code>STATIC_HERMES_ENABLE_LEAN_ARCHIVE=0</code> to disable the lean archive for builds.</p><p>Run the build command with <code>--types-only</code> to generate guest types without producing the component. Those declarations are consumed by TypeScript and the editor. They are build output, so edit the plugin source and package configuration rather than generated files.</p><h2 id="build-constraints" tabindex="-1">Build constraints <a class="header-anchor" href="#build-constraints" aria-label="Permalink to &quot;Build constraints&quot;">​</a></h2><p>Static Hermes uses the pinned Pumpkin API WIT and WASI 2. Keep the workspace&#39;s Pumpkin API version aligned with the test harness server version. Requested WASI capabilities and Pumpkin permissions must match the APIs the plugin uses.</p><p>Identical source builds are not byte-for-byte reproducible. Signing or publishing workflows must use the exact artifact from the build job instead of rebuilding it later.</p>',8)])])}const m=t(n,[["render",d]]);export{h as __pageData,m as default};
